/**
 * Refuses every change asked of an archived sheet, before anything is written: any request to a
 * sheet other than a read, unless its handler is {@link OpenToViewer} (loading the sheet, or a bulk
 * change that itself refuses each selected item on an archived sheet).
 */
@Configuration
public class ArchivedGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final SheetRepository sheets;

    public ArchivedGuard(SheetRepository sheets) {
        this.sheets = sheets;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) return true;
        if (!(handler instanceof HandlerMethod method) || method.hasMethodAnnotation(OpenToViewer.class)) return true;
        String sheetId = sheetId(request);
        if (sheetId == null) return true;
        if (sheets.findById(sheetId).map(Sheet::isArchived).orElse(false)) throw new SheetArchivedException();
        return true;
    }

    /** The sheet the request is for: its sheetId path variable, or the id of a request to the sheet itself. */
    private static String sheetId(HttpServletRequest request) {
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (vars == null) return null;
        return vars.getOrDefault("sheetId", vars.get("id"));
    }
}
package net.officefloor.hq.app.asof;


/**
 * The as-of view, which belongs to the user's screen: a request to a sheet carrying an
 * {@value #HEADER} date is shown as the sheet stood at the end of that date, and a change asked
 * with one is refused before anything is written. Every other change made to a sheet that has gone
 * through is marked for {@link SheetHistoryFilter} to record in its {@link SheetHistory}.
 *
 * <p>A read as of a date runs in a transaction that puts the sheet back as it stood then, with that
 * date as its today, and is rolled back once the read is answered, so it changes nothing and audits
 * nothing.
 */
@Configuration
public class AsOfGuard implements WebMvcConfigurer, HandlerInterceptor {

    /** The request header carrying the user's as-of date (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private static final String VIEW = AsOfGuard.class.getName() + ".view";

    /** A read as of a date under way: its transaction and the lock it holds on its sheet. */
    private record View(TransactionStatus transaction, ReentrantLock lock) {}

    private final SheetHistory history;
    private final PlatformTransactionManager transactions;
    /** One as-of read of a sheet at a time: each puts back the same rows. */
    private final Map<String, ReentrantLock> locks = new ConcurrentHashMap<>();

    public AsOfGuard(SheetHistory history, PlatformTransactionManager transactions) {
        this.history = history;
        this.transactions = transactions;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (!(handler instanceof HandlerMethod method)) return true;
        String sheetId = sheetId(request);
        String header = request.getHeader(HEADER);
        if (sheetId == null || header == null || header.isBlank()) return true;
        if (!isRead(request) && !method.hasMethodAnnotation(AsOfRead.class)) throw new AsOfRefusedException();
        LocalDate asOf;
        try {
            asOf = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new AsOfRefusedException();
        }
        // a sheet never started is started as usual
        if (!history.exists(sheetId)) return true;
        ReentrantLock lock = locks.computeIfAbsent(sheetId, id -> new ReentrantLock());
        lock.lock();
        TransactionStatus transaction = null;
        try {
            transaction = transactions.getTransaction(new DefaultTransactionDefinition());
            history.restore(sheetId, asOf);
        } catch (RuntimeException e) {
            if (transaction != null) transactions.rollback(transaction);
            lock.unlock();
            throw e;
        }
        request.setAttribute(VIEW, new View(transaction, lock));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        if (request.getAttribute(VIEW) instanceof View view) {
            request.removeAttribute(VIEW);
            try {
                transactions.rollback(view.transaction());
            } finally {
                view.lock().unlock();
            }
            return;
        }
        if (isRead(request) || ex != null || response.getStatus() >= 400) return;
        String sheetId = sheetId(request);
        if (sheetId != null) request.setAttribute(SheetHistoryFilter.CHANGED, sheetId);
    }

    private static boolean isRead(HttpServletRequest request) {
        return HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod());
    }

    /** The sheet the request is for: its sheetId path variable, or the id of a request to the sheet itself. */
    private static String sheetId(HttpServletRequest request) {
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (vars == null) return null;
        return vars.getOrDefault("sheetId", vars.get("id"));
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** A void reason on the sheet. */
interface VoidReasonView {
  id: number;
  reason: string;
}

// The sheet's void reasons, each once. While any are on the list, a claim is voided only with one
// of them, chosen on the claim; the summary counts the VOID claims voided with each.
@Component({
  selector: 'app-void-reasons',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="void-reasons-heading">
      <h2 id="void-reasons-heading">Void reasons</h2>
      <form [formGroup]="form" (ngSubmit)="add()" aria-label="Add a void reason">
        <label for="void-reason-text">Void reason</label>
        <input id="void-reason-text" data-testid="void-reason-text" formControlName="reason" />
        <button type="submit" data-testid="void-reason-add">Add void reason</button>
        @if (error()) {
          <p role="alert" class="error" data-testid="void-reason-error">{{ error() }}</p>
        }
      </form>
      <ul aria-label="Void reasons">
        @for (r of session.voidReasons(); track r) {
          <li [attr.data-testid]="'void-reason-row-' + r">{{ r }}</li>
        }
      </ul>
    </section>
  `,
})
export class VoidReasons {
  private readonly http = inject(HttpClient);
  protected readonly session = inject(Session);

  protected readonly error = signal('');
  protected readonly form = new FormGroup({ reason: new FormControl('', { nonNullable: true }) });
  private submitting = false;

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      this.session.voidReasons.set([]);
      this.error.set('');
      if (id) void this.load(id);
    });
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }

  private base(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/void-reasons`;
  }

  private async load(sheet: string): Promise<void> {
    try {
      const list = await firstValueFrom(this.http.get<VoidReasonView[]>(this.base(sheet), { headers: this.headers() }));
      if (this.session.sheetId() === sheet) this.session.voidReasons.set(list.map((r) => r.reason));
    } catch {
      if (this.session.sheetId() === sheet) this.error.set('Could not load the void reasons of this sheet.');
    }
  }

  /** Add a reason to the sheet's list, trimmed; a blank one or one already on the list is refused. */
  protected async add(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const reason = this.form.controls.reason.value.trim().replace(/\s+/g, ' ');
    if (reason === '' || reason.length > 200) {
      this.error.set('Enter a void reason (at most 200 characters).');
      return;
    }
    if (this.session.voidReasons().includes(reason)) {
      this.error.set('That reason is already on the list.');
      return;
    }
    this.submitting = true;
    try {
      const saved = await firstValueFrom(
        this.http.post<VoidReasonView>(this.base(sheet), { reason }, { headers: this.headers() }),
      );
      if (this.session.sheetId() !== sheet) return;
      this.session.voidReasons.update((list) => (list.includes(saved.reason) ? list : [...list, saved.reason]));
    } catch (e) {
      if (this.session.sheetId() !== sheet) return;
      this.error.set(e instanceof HttpErrorResponse && e.status === 409
        ? 'That reason is already on the list.'
        : 'Could not add that void reason.');
    } finally {
      this.submitting = false;
    }
  }
}
